import openpyxl
from openpyxl.utils import get_column_letter
wb=openpyxl.load_workbook('/root/data/workbook.xlsx', data_only=False)
ds=wb['Data']
for target in [2019,2020,2021,2022,2023,'2019','2020','2021','2022','2023']:
    hits=[]
    for row in ds.iter_rows():
        for cell in row:
            if cell.value == target:
                hits.append(cell.coordinate)
    print(target, hits)
print('merged ranges', list(ds.merged_cells.ranges))
print('hidden rows/cols')
for i, dim in ds.row_dimensions.items():
    if dim.hidden:
        print('hidden row', i)
for k, dim in ds.column_dimensions.items():
    if dim.hidden:
        print('hidden col', k)
